/* ---------- Thème, toasts, ripple ---------- */
const applyTheme = t => { document.documentElement.dataset.theme = t; localStorage.setItem('cm_theme', t); };
applyTheme(localStorage.getItem('cm_theme') || (matchMedia('(prefers-color-scheme:dark)').matches ? 'dark' : 'light'));
function toast(msg, type = 'ok') {
  let box = $('.toasts'); if (!box) { box = document.createElement('div'); box.className = 'toasts'; document.body.appendChild(box); }
  const t = document.createElement('div'); t.className = 'toast ' + type; t.innerHTML = `<span>${type === 'ok' ? '✓' : '⚠'}</span><span>${esc(msg)}</span>`; box.appendChild(t);
  setTimeout(() => { t.classList.add('out'); setTimeout(() => t.remove(), 320); }, type === 'error' ? 5200 : 2600);
}
window.alert = m => toast(String(m), 'error');
document.addEventListener('click', e => { const b = e.target.closest('.btn'); if (!b || b.disabled) return; const r = document.createElement('span'), d = Math.max(b.clientWidth, b.clientHeight), x = b.getBoundingClientRect(); r.className = 'ripple'; r.style.cssText = `width:${d}px;height:${d}px;left:${e.clientX - x.left - d / 2}px;top:${e.clientY - x.top - d / 2}px`; b.appendChild(r); setTimeout(() => r.remove(), 600); });

/* ---------- API : session expirée + confirmation des enregistrements ---------- */
const _api = api;
api = async function (url, opts = {}) {
  try { const d = await _api(url, opts); if (opts.method && opts.method !== 'GET' && !/^\/(auth|setup|ocr|me\/2fa\/setup)/.test(url)) toast('Enregistré avec succès'); return d; }
  catch (e) { if (/Session expirée|authentification requise/i.test(e.message) && token) { localStorage.removeItem('cm_token'); token = null; login('Votre session a expiré. Reconnectez-vous.'); } throw e; }
};
async function download(url, name) {
  const r = await fetch('/api' + url, { headers: { Authorization: 'Bearer ' + token } }); if (!r.ok) return toast((await r.json().catch(() => ({}))).error || 'Téléchargement impossible', 'error');
  const a = document.createElement('a'); a.href = URL.createObjectURL(await r.blob()); a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 3000);
}

