const QUICK = [['invoices', 'Nouvelle facture', '#addInvoice', 'invoices'], ['invoices', 'Scanner une facture (OCR)', '#scanInvoice', 'templates'], ['payments', 'Nouveau règlement', '#addPayment', 'payments'], ['accounting', 'Saisie d’écriture', '#newEntry', 'accounting'], ['assets', 'Nouvelle immobilisation', '#newAsset', 'assets'], ['bank-reconcile', 'Importer un relevé bancaire', '#imp', 'bank-reconcile']];
async function quick(i) { tab = QUICK[i][0]; renderShell(); await renderTab(); setTimeout(() => $(QUICK[i][2])?.click(), 90); }
let lastInd = null;
const closeDrop = () => document.querySelectorAll('.tn.open,.create.open,.usr.open').forEach(x => x.classList.remove('open'));
const closeDrawer = () => { closeDrop(); $('#sheet')?.classList.remove('open'); };
document.addEventListener('click', e => { if (!e.target.closest('.tn,.create,.usr')) closeDrop(); });
