  v.querySelectorAll('[data-rv]').forEach(a => a.onclick = async e => { e.preventDefault(); const [u, c] = a.dataset.rv.split(':'); if (confirm('Retirer cet accès ?')) { await api(`/users/${u}/access/${c}`, { method: 'DELETE' }); refresh(); } });
